CREATE TABLE "agent_actions" ("id" TEXT NOT NULL, "run_id" TEXT NOT NULL REFERENCES agent_runs (id), "tool" TEXT NOT NULL, "args" TEXT NOT NULL, "args_hash" TEXT NOT NULL, "risk" TEXT NOT NULL, "state" INTEGER NOT NULL, "block_reason" TEXT NULL, "result_ref" TEXT NULL, "error_code" TEXT NULL, "created_at" INTEGER NOT NULL, "decided_at" INTEGER NULL, "completed_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "agent_runs" ("id" TEXT NOT NULL, "trigger" TEXT NOT NULL, "model" TEXT NULL, "prompt_version" TEXT NULL, "input_tokens" INTEGER NOT NULL DEFAULT 0, "output_tokens" INTEGER NOT NULL DEFAULT 0, "latency_ms" INTEGER NULL, "status" TEXT NOT NULL, "started_at" INTEGER NOT NULL, "finished_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "audit_logs" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "actor" TEXT NOT NULL, "action" TEXT NOT NULL, "target_type" TEXT NULL, "target_id" TEXT NULL, "outcome" TEXT NOT NULL, "at" INTEGER NOT NULL);
CREATE TABLE "commitments" ("id" TEXT NOT NULL, "source" INTEGER NOT NULL, "source_ref" TEXT NULL, "confidence" REAL NOT NULL DEFAULT 1.0, "sensitivity" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "description" TEXT NOT NULL, "counterparty" TEXT NULL, "due_at" INTEGER NULL, "status" TEXT NOT NULL DEFAULT 'open', "task_id" TEXT NULL REFERENCES tasks (id), PRIMARY KEY ("id"));
CREATE TABLE "document_chunks" ("id" TEXT NOT NULL, "document_id" TEXT NOT NULL REFERENCES documents (id), "ordinal" INTEGER NOT NULL, "body" TEXT NOT NULL, "page" INTEGER NULL, "embedding" BLOB NULL, PRIMARY KEY ("id"));
CREATE TABLE "document_extractions" ("id" TEXT NOT NULL, "document_id" TEXT NOT NULL REFERENCES documents (id), "field" TEXT NOT NULL, "value" TEXT NOT NULL, "confidence" REAL NOT NULL, "page" INTEGER NULL, "review_status" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "documents" ("id" TEXT NOT NULL, "source" INTEGER NOT NULL, "source_ref" TEXT NULL, "confidence" REAL NOT NULL DEFAULT 1.0, "sensitivity" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "file_name" TEXT NOT NULL, "mime_type" TEXT NOT NULL, "sha256" TEXT NOT NULL, "size_bytes" INTEGER NOT NULL, "blob_path" TEXT NOT NULL, "doc_type" TEXT NULL, "classification_confidence" REAL NULL, "ocr_status" TEXT NOT NULL DEFAULT 'pending', "extraction_status" TEXT NOT NULL DEFAULT 'pending', "entity_id" TEXT NULL REFERENCES entities (id), PRIMARY KEY ("id"));
CREATE TABLE "emergency_fields" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, "show_on_card" INTEGER NOT NULL DEFAULT 0 CHECK ("show_on_card" IN (0, 1)), "updated_at" INTEGER NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "entities" ("id" TEXT NOT NULL, "source" INTEGER NOT NULL, "source_ref" TEXT NULL, "confidence" REAL NOT NULL DEFAULT 1.0, "sensitivity" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "type" TEXT NOT NULL, "display_name" TEXT NOT NULL, "attributes" TEXT NOT NULL DEFAULT '{}', PRIMARY KEY ("id"));
CREATE TABLE "entity_dates" ("id" TEXT NOT NULL, "source" INTEGER NOT NULL, "source_ref" TEXT NULL, "confidence" REAL NOT NULL DEFAULT 1.0, "sensitivity" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "entity_id" TEXT NOT NULL REFERENCES entities (id), "kind" TEXT NOT NULL, "date" INTEGER NOT NULL, "recurrence_rule" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "entity_relationships" ("id" TEXT NOT NULL, "source" INTEGER NOT NULL, "source_ref" TEXT NULL, "confidence" REAL NOT NULL DEFAULT 1.0, "sensitivity" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "from_entity" TEXT NOT NULL REFERENCES entities (id), "to_entity" TEXT NOT NULL REFERENCES entities (id), "relation" TEXT NOT NULL, "valid_from" INTEGER NULL, "valid_to" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "events" ("id" TEXT NOT NULL, "source" INTEGER NOT NULL, "source_ref" TEXT NULL, "confidence" REAL NOT NULL DEFAULT 1.0, "sensitivity" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "title" TEXT NOT NULL, "starts_at" INTEGER NOT NULL, "ends_at" INTEGER NULL, "location" TEXT NULL, "recurrence_rule" TEXT NULL, "external_ref" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "memories" ("id" TEXT NOT NULL, "source" INTEGER NOT NULL, "source_ref" TEXT NULL, "confidence" REAL NOT NULL DEFAULT 1.0, "sensitivity" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "kind" INTEGER NOT NULL, "category" TEXT NOT NULL, "content" TEXT NOT NULL, "subject" TEXT NULL, "predicate" TEXT NULL, "value" TEXT NULL, "valid_from" INTEGER NOT NULL, "valid_to" INTEGER NULL, "superseded_by" TEXT NULL REFERENCES memories (id), "user_editable" INTEGER NOT NULL DEFAULT 1 CHECK ("user_editable" IN (0, 1)), "version" INTEGER NOT NULL DEFAULT 1, PRIMARY KEY ("id"));
CREATE TABLE "memory_versions" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "memory_id" TEXT NOT NULL REFERENCES memories (id), "version" INTEGER NOT NULL, "content" TEXT NOT NULL, "value" TEXT NULL, "valid_to" INTEGER NULL, "changed_by" TEXT NOT NULL, "change_reason" TEXT NULL, "at" INTEGER NOT NULL);
CREATE TABLE "permissions" ("capability" TEXT NOT NULL, "granted" INTEGER NOT NULL CHECK ("granted" IN (0, 1)), "autonomous" INTEGER NOT NULL DEFAULT 0 CHECK ("autonomous" IN (0, 1)), "scope" TEXT NOT NULL DEFAULT '{}', "granted_via" TEXT NOT NULL, "granted_at" INTEGER NOT NULL, "expires_at" INTEGER NULL, PRIMARY KEY ("capability"));
CREATE TABLE "reminders" ("id" TEXT NOT NULL, "source" INTEGER NOT NULL, "source_ref" TEXT NULL, "confidence" REAL NOT NULL DEFAULT 1.0, "sensitivity" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "title" TEXT NOT NULL, "fire_at" INTEGER NOT NULL, "target_id" TEXT NULL, "status" TEXT NOT NULL DEFAULT 'scheduled', "snoozed_until" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "suggestions" ("id" TEXT NOT NULL, "detector" TEXT NOT NULL, "subject_id" TEXT NOT NULL, "reason_code" TEXT NOT NULL, "explanation_facts" TEXT NOT NULL, "due_at" INTEGER NULL, "surfaced_at" INTEGER NOT NULL, "dismissed_at" INTEGER NULL, "snoozed_until" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "tasks" ("id" TEXT NOT NULL, "source" INTEGER NOT NULL, "source_ref" TEXT NULL, "confidence" REAL NOT NULL DEFAULT 1.0, "sensitivity" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "title" TEXT NOT NULL, "notes" TEXT NULL, "status" INTEGER NOT NULL DEFAULT 0, "priority" INTEGER NOT NULL DEFAULT 1, "due_at" INTEGER NULL, "all_day" INTEGER NOT NULL DEFAULT 0 CHECK ("all_day" IN (0, 1)), "recurrence_rule" TEXT NULL, "project_entity_id" TEXT NULL REFERENCES entities (id), "completed_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE INDEX idx_actions_state ON agent_actions (state);
CREATE INDEX idx_audit_at ON audit_logs (at);
CREATE INDEX idx_entity_dates_date ON entity_dates (date) WHERE deleted_at IS NULL;
CREATE INDEX idx_events_start ON events (starts_at) WHERE deleted_at IS NULL;
CREATE INDEX idx_memories_active ON memories (subject, predicate) WHERE valid_to IS NULL AND deleted_at IS NULL;
CREATE INDEX idx_reminders_fire ON reminders (status, fire_at) WHERE deleted_at IS NULL;
CREATE INDEX idx_tasks_due ON tasks (status, due_at) WHERE deleted_at IS NULL;
PRAGMA user_version = 2;
